import type { FC } from 'react';
import { motion } from 'framer-motion';
import ProjectGrid from '../components/ProjectGrid';

const Projects: FC = () => {
  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="pt-24"
    >
      <ProjectGrid />
    </motion.div>
  );
};

export default Projects;
